<style scoped lang="scss" src="./avatar.scss"></style>

<script lang="js">
import { Component, Prop, Vue } from "vue-property-decorator";
import { AvatarSize, AvatarSizeValues, AvatarMode, AvatarModeValues } from "./avatar.constants.js";
import { has } from "../../util/has";

/**
 * Displays an avatar rendition of an image. Good for displaying profile
 * pictures or company logos.
 */
@Component
export default class Avatar extends Vue {
  /** The image source to render for this avatar */
  @Prop({ type: String, default: "" }) image;
  /** The sizing options for this avatar */
  @Prop({
    type: String,
    default: AvatarSize.MEDIUM,
    validator: has(AvatarSizeValues)
  }) size;
  /** The rendering mode */
  @Prop({
    type: String,
    default: AvatarMode.DEFAULT,
    validator: has(AvatarModeValues)
  }) mode;
  /** Set to true to make the image appear in gray tones */
  @Prop({ type: Boolean }) grayscale;

  @Prop({ type: Boolean, default: true }) isRound;

  get style() {
    if(this.size === AvatarSize.AUTO) {
      return {}
    }

    return {
      backgroundImage: `url(${this.image})`
    }
  }

  get imageSrc() {
    if(this.size === AvatarSize.AUTO) {
      return this.image;
    }

    return "";
  }

  get grayscaleClass() {
    return this.grayscale ? "Avatar--gray" : null;
  }

  get roundStyle() {
    if(!this.isRound) {
      return {
        borderRadius: '0px'
      };
    }

    return {};
  }

  handleClick() {
    /**
     * Click event when the avatar is clicked by the user.
     *
     * @event click
     */
    this.$emit("click");
  }
}
</script>

<template>
  <div
    :class="['Avatar', mode, size, grayscaleClass]"
    :style="[style, roundStyle]"
    @click="handleClick"
  >
    <img :src="imageSrc" />
  </div>
</template>
